<?php require_once '../config.php';require_admin();$pdo=db();if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$s=$pdo->prepare("UPDATE orders SET status=? WHERE id=?");$s->execute([$_POST['status'],(int)$_POST['id']]);flash('success','Order status updated.');header('Location: orders.php');exit;}$orders=$pdo->query("SELECT o.*,c.name,c.phone,c.address FROM orders o JOIN customers c ON c.id=o.customer_id ORDER BY o.id DESC")->fetchAll();$statuses=['Pending','Confirmed','Packed','Shipped','Delivered','Cancelled'];?><!doctype html><html><head><meta charset="utf-8"><title>Orders</title><link rel="stylesheet" href="../assets/style.css"></head><body class="adminbody"><header><div class="top"><a class="brand" href="../index.php"><span>📖</span><b>Kalpalatha<small>Orders</small></b></a><div class="links"><a href="index.php">Dashboard</a><a href="logout.php">Logout</a></div></div></header><main class="dash"><section class="tablecard"><h1>Orders</h1><div class="table-scroll"><table><tr><th>Order</th><th>Customer</th><th>Phone</th><th>Address</th><th>Total</th><th>Status</th></tr><?php foreach($orders as $o):?><tr><td>#KB<?=str_pad($o['id'],5,'0',STR_PAD_LEFT)?><br><small><?=e($o['created_at'])?></small></td><td><?=e($o['name'])?></td><td><?=e($o['phone'])?></td><td><?=e($o['address'])?></td><td><?=money((float)$o['total'])?></td><td><form method="post"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="id" value="<?=$o['id']?>"><select name="status" onchange="this.form.submit()"><?php foreach($statuses as $s):?><option <?=$s===$o['status']?'selected':''?>><?=$s?></option><?php endforeach;?></select></form></td></tr><?php endforeach;?></table></div></section></main></body></html>